import { execFileSync } from 'node:child_process';

const range = process.argv[2];

if (!range) {
  console.error('Usage: node .github/scripts/validate-commit-messages.mjs <commit-range>');
  process.exit(2);
}

const allowedTypes = new Set(['feat', 'fix', 'refactor', 'perf', 'docs', 'test', 'chore', 'style', 'ci']);
const subjectPattern = /^([a-z]+)\(([a-z0-9-]+)\): (.+)$/;
const recordSeparator = '\x1e';
const fieldSeparator = '\x1f';

function git(args) {
  return execFileSync('git', args, { encoding: 'utf8' }).trim();
}

function getCommits(commitRange) {
  const format = `%H${fieldSeparator}%P${fieldSeparator}%s${fieldSeparator}%b${recordSeparator}`;
  const output = git(['log', '--no-color', `--format=${format}`, commitRange]);
  if (!output) return [];
  return output
    .split(recordSeparator)
    .map(chunk => chunk.trim())
    .filter(Boolean)
    .map(chunk => {
      const [sha, parents, subject, ...bodyParts] = chunk.split(fieldSeparator);
      return {
        sha,
        isMerge: (parents || '').trim().split(' ').filter(Boolean).length >= 2,
        subject: subject || '',
        body: bodyParts.join(fieldSeparator) || '',
      };
    });
}

function isAutoGeneratedGitHubCommit(subject) {
  return subject.startsWith('Merge ') || subject.startsWith('Revert "');
}

function validateCommit({ sha, isMerge, subject, body }) {
  const errors = [];

  // 머지 커밋(부모 2개 이상)은 제목 규칙 대상이 아니다 — git이 생성하는
  // 기본 제목이나 'merge: ...' 커스텀 제목 모두 일반 커밋 형식과 다르고,
  // 실질 변경 내용은 병합된 커밋들이 담는다.
  if (isMerge) return errors;
  if (isAutoGeneratedGitHubCommit(subject)) return errors;

  const match = subject.match(subjectPattern);
  if (!match) {
    errors.push('제목은 `<type>(<scope>): <한국어 제목>` 형식이어야 합니다.');
  } else {
    const [, type, scope, title] = match;
    if (!allowedTypes.has(type)) {
      errors.push(`type '${type}'은 허용되지 않습니다. 허용값: ${[...allowedTypes].join(', ')}`);
    }
    if (!scope) errors.push('scope가 비어 있습니다. 예: server, customer, owner, ci');
    if (!title.trim()) errors.push('제목 본문이 비어 있습니다.');
    if (subject.length > 72) errors.push(`제목은 72자 이하여야 합니다. 현재 ${subject.length}자입니다.`);
  }

  if (!body.includes('Why:')) {
    errors.push('본문에 `Why:`가 필요합니다.');
  }

  if (!/^\s*-\s+/m.test(body)) {
    errors.push('본문에 최소 1개 이상의 bullet(`- ...`)이 필요합니다.');
  }

  if (!body.includes('🤖 Generated with')) {
    errors.push('AI 주도 커밋은 `🤖 Generated with <tool>` 마커가 필요합니다.');
  }

  return errors.map(message => ({ sha, subject, message }));
}

let commits;
try {
  commits = getCommits(range);
} catch (error) {
  console.error(`커밋 범위를 읽지 못했습니다: ${range}`);
  console.error(error.message);
  process.exit(2);
}

const failures = commits.flatMap(validateCommit);

if (failures.length > 0) {
  console.error('\n커밋 메시지 컨벤션 위반이 있습니다.');
  console.error('형식은 COMMIT_CONVENTION.md를 따르세요.\n');

  for (const failure of failures) {
    console.error(`- ${failure.sha.slice(0, 12)} ${failure.subject}`);
    console.error(`  ${failure.message}`);
  }

  console.error('\n예시:');
  console.error(`fix(server): 추천곡 상태 전이 오류 수정

Why: played 상태에서 accepted로 되돌아가는 전이가 허용되어 종료된 곡이 다시 큐에 노출될 수 있었다.

- server/src/services/recommendation.service.js: terminal status 전이 차단
- server/tests/transition.test.mjs: 종료 상태 역방향 전이 테스트 추가

Decision: DB trigger가 아니라 service layer에서 막았다. 현재 상태 변경 진입점이 updateStatus로 모여 있어 테스트와 유지보수가 쉽기 때문이다.

🤖 Generated with Codex`);
  process.exit(1);
}

console.log(`커밋 메시지 컨벤션 검사 통과: ${commits.length}개 커밋`);
